package fr.noxodev.noxoclaim.listeners;
import fr.noxodev.noxoclaim.NoxoClaim; import org.bukkit.*; import org.bukkit.event.*; import org.bukkit.event.player.PlayerInteractEvent; import org.bukkit.inventory.ItemStack;
public final class WandListener implements Listener {private final NoxoClaim p;public WandListener(NoxoClaim p){this.p=p;}private boolean isWand(ItemStack i){return i!=null&&i.getType()==Material.valueOf(p.getConfig().getString("wand.material","GOLDEN_SHOVEL"))&&i.hasItemMeta()&&i.getItemMeta().hasDisplayName()&&i.getItemMeta().getDisplayName().equals("§bWand de claim");}@EventHandler public void click(PlayerInteractEvent e){if(!isWand(e.getItem())||e.getClickedBlock()==null)return;e.setCancelled(true);var u=e.getPlayer().getUniqueId();var l=e.getClickedBlock().getLocation();if(e.getAction().isLeftClick()){p.selections().setFirst(u,l);e.getPlayer().sendMessage("§bPosition 1: §f"+l.getBlockX()+", "+l.getBlockY()+", "+l.getBlockZ());}else if(e.getAction().isRightClick()){p.selections().setSecond(u,l);e.getPlayer().sendMessage("§bPosition 2: §f"+l.getBlockX()+", "+l.getBlockY()+", "+l.getBlockZ());}}}
